<!-- Video Production Workflow Section -->
<section class="workflow-section">
    <div class="container">
        <h2 class="workflow-heading">What Does BrandStory Offer for Your Video Production Requirements?</h2>
        <p class="workflow-subtext">BrandStory, the leading video production company in Dubai, creates high-quality, engaging videos aligned with your brand identity and marketing goals. Incorporating the brand's voice, values, and aesthetics, we make sure that the outputs resonate well with the intended audience. We handle the entire process of video production from discovery to the final, ready-to-launch stage with our industry expertise, well-planned execution strategy, skilled team and cutting-edge tools and technologies.</p>
        
        <div class="row">
            <!-- Left Side Accordion -->
            <div class="col-lg-6 col-md-12">
                <div class="workflow-accordion">
                    <!-- Tab 1: Discovery -->
                    <div class="workflow-acc-item active" data-target="discovery">
                        <div class="workflow-acc-header">
                            <h3 class="workflow-acc-title">Discovery</h3>
                            <span class="workflow-acc-icon"></span>
                        </div>
                        <div class="workflow-acc-content">
                            <p class="workflow-acc-desc">In-depth research, deliberate questioning, and attentive listening to gain a profound understanding of the client's needs, goals, and market landscape.</p>
                            <div class="workflow-acc-grid">
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>Project scoping and goal definition</div>
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>Stakeholder interviews and requirements gathering</div>
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>User research and persona development</div>
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>Competitive analysis and market research</div>
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>Information architecture and user flow mapping</div>
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>Usability testing and feedback collection</div>
                            </div>
                        </div>
                    </div>
                    
                    <!-- Tab 2: Pre-Production -->
                    <div class="workflow-acc-item" data-target="pre-production">
                        <div class="workflow-acc-header">
                            <h3 class="workflow-acc-title">Pre-Production</h3>
                            <span class="workflow-acc-icon"></span>
                        </div>
                        <div class="workflow-acc-content">
                            <p class="workflow-acc-desc">Detailed planning, scriptwriting, storyboarding, scheduling, casting, and location scouting to prepare everything before the camera rolls.</p>
                            <div class="workflow-acc-grid">
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>Scriptwriting and editing</div>
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>Storyboarding and style frames</div>
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>Location scouting and permits</div>
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>Casting and talent sourcing</div>
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>Production scheduling and budget planning</div>
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>Crew hiring and equipment list prep</div>
                            </div>
                        </div>
                    </div>
                    
                    <!-- Tab 3: Production -->
                    <div class="workflow-acc-item" data-target="production">
                        <div class="workflow-acc-header">
                            <h3 class="workflow-acc-title">Production</h3>
                            <span class="workflow-acc-icon"></span>
                        </div>
                        <div class="workflow-acc-content">
                            <p class="workflow-acc-desc">The actual shooting phase where the director, crew, and talent work together to capture all raw footage, interviews, and visuals according to the storyboard.</p>
                            <div class="workflow-acc-grid">
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>High-quality cinematography and filming</div>
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>Professional audio recording</div>
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>Multi-camera setup configurations</div>
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>Directing talent and interviews</div>
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>Lighting setups and scene layout</div>
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>Raw footage logging and backup</div>
                            </div>
                        </div>
                    </div>
                    
                    <!-- Tab 4: Post-Production -->
                    <div class="workflow-acc-item" data-target="post-production">
                        <div class="workflow-acc-header">
                            <h3 class="workflow-acc-title">Post-Production</h3>
                            <span class="workflow-acc-icon"></span>
                        </div>
                        <div class="workflow-acc-content">
                            <p class="workflow-acc-desc">Where the magic comes together: editing the raw footage, adding transitions, sound effects, voiceovers, background score, color grading, and final rendering.</p>
                            <div class="workflow-acc-grid">
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>Video editing and assembly</div>
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>Sound design and audio mixing</div>
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>Voiceover recording and sync</div>
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>Color grading and color correction</div>
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>Motion graphics and 2D/3D animation</div>
                                <div class="workflow-acc-bullet"><span class="bullet-icon"></span>Final formatting, rendering, and delivery</div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            
            <!-- Right Side Graphic / Connectors -->
            <div class="col-lg-6 col-md-12 mt-5 mt-lg-0">
                <div class="workflow-panel">
                    <!-- SVG Connection Lines -->
                    <svg class="workflow-lines-svg" style="position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none; z-index: 1;">
                        <!-- From top to Discovery -->
                        <line x1="60%" y1="0" x2="60%" y2="15%" stroke="rgba(255, 255, 255, 0.15)" stroke-width="1.5" stroke-dasharray="4" />
