                        <!-- From Pre-Production to Production -->
                        <path d="M 80% 45% V 62% H 59%" stroke="rgba(255, 255, 255, 0.15)" stroke-width="1.5" stroke-dasharray="4" fill="none" />
                        <!-- From Production to Post-Production -->
                        <path d="M 54% 68% V 83% H 76%" stroke="rgba(255, 255, 255, 0.15)" stroke-width="1.5" stroke-dasharray="4" fill="none" />
