<script>
document.addEventListener('DOMContentLoaded', function() {
    const accItems = document.querySelectorAll('.workflow-acc-item');
    const nodes = document.querySelectorAll('.workflow-node');
    
    // Accordion clicks
    accItems.forEach(item => {
        const header = item.querySelector('.workflow-acc-header');
        header.addEventListener('click', function() {
            // Remove active class from all accordion items
            accItems.forEach(acc => acc.classList.remove('active'));
            // Add active class to clicked item
            item.classList.add('active');
            
            // Highlight corresponding node
            const targetNode = item.getAttribute('data-target');
            nodes.forEach(node => {
                if (node.classList.contains('node-' + targetNode)) {
                    node.classList.add('active');
                } else {
                    node.classList.remove('active');
                }
            });
        });
    });
    
    // Flowchart Node clicks
    nodes.forEach(node => {
        node.addEventListener('click', function() {
            let targetNode = '';
            if (node.classList.contains('node-discovery')) targetNode = 'discovery';
            else if (node.classList.contains('node-pre-production')) targetNode = 'pre-production';
            else if (node.classList.contains('node-production')) targetNode = 'production';
            else if (node.classList.contains('node-post-production')) targetNode = 'post-production';
            
            if (targetNode) {
                const accItem = document.querySelector(`.workflow-acc-item[data-target="${targetNode}"]`);
                if (accItem) {
                    const header = accItem.querySelector('.workflow-acc-header');
                    if (header) {
                        header.click();
                    }
                }
            }
        });
    });
});
</script>